"""Original DBMS label cards; measured contexts, no original-file mutations."""
from pathlib import Path
import json,html
r=Path(__file__).resolve().parents[2];out=r/'artifacts/replica/windows-download';(out/'dbmsoption-original.css').write_text((r/'docs/replica/source/original.css').read_text())
engines=[('SQL Server','Microsoft · 1433'),('PostgreSQL','PostgreSQL · 5432'),('MySQL','MySQL · 3306'),('MariaDB','MariaDB · 3306')];cases=[]
for lang in ['ko','en']:
 for compact in [False,True]:
  for width in ([213,240,320] if not compact else [163.5,180,207.5]):
   for name,desc in engines:cases.append(dict(id=f'{lang}-{int(compact)}-{width}-{name.replace(" ","")}',lang=lang,compact=compact,width=width,name=name,description=desc,selected=False,hover=False,focus=False))
  for selected in [False,True]:
   for hover in [False,True]:
    for focus in [False,True]:cases.append(dict(id=f'{lang}-{int(compact)}-state-{int(selected)}{int(hover)}{int(focus)}',lang=lang,compact=compact,width=207.5 if compact else 240,name=engines[0][0],description=engines[0][1],selected=selected,hover=hover,focus=focus))
parts=['<!doctype html><meta charset="utf-8"><title>DbmsOption · original isolation</title><link rel="stylesheet" href="dbmsoption-original.css"><style>body{min-width:1280px;height:10000px}.fixture{position:absolute}.fixture:not(.compact) .dbms-option{grid-template-columns:30px 1fr 20px;padding:16px;gap:12px}.fixture:not(.compact) .dbms-option>.svg{display:block}.fixture:not(.compact) .dbms-option small{font-size:11px}.fixture.compact .dbms-option{grid-template-columns:1fr 20px;padding:14px;gap:8px}.fixture.compact .dbms-option>.svg{display:none}.fixture.compact .dbms-option small{font-size:10px}.dbms-option.fixture-hover{background:#383b44;border-color:#a7b1ff}.dbms-option:has(.fixture-focus){outline:3px solid #a7b1ff;outline-offset:3px}.dbms-option,.dbms-option *{transition:none!important}.fixture-focus{outline:3px solid #a7b1ff;outline-offset:3px}</style>']
svg='<svg class="svg" viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="12" cy="5" rx="8" ry="3"></ellipse><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"></path></svg>'
for i,c in enumerate(cases):
 parts.append(f'<div class="fixture {"compact" if c["compact"] else ""}" lang="{c["lang"]}" style="left:{30+(i%3)*360}px;top:{30+(i//3)*120}px;width:{c["width"]}px"><label data-id="{c["id"]}" class="dbms-option {"fixture-hover" if c["hover"] else ""}">{svg}<span><strong>{html.escape(c["name"])}</strong><small>{html.escape(c["description"])}</small></span><input type="radio" class="{"fixture-focus" if c["focus"] else ""}" name="{c["id"]}" value="{html.escape(c["name"])}" {"checked" if c["selected"] else ""} aria-label="{html.escape(c["name"])}"></label></div>')
parts.append('''<button type="button" id="dbmsoption-record" style="position:fixed;right:20px;top:20px">Record DbmsOption</button><script>
function measurements(){return [...document.querySelectorAll('.dbms-option')].map(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);const box=c=>{const q=c.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}};const svg=e.querySelector('svg'),title=e.querySelector('strong'),small=e.querySelector('small');return{id:e.dataset.id,rect:{width:r.width,height:r.height},body:box(e.querySelector('span')),icon:getComputedStyle(svg).display==='none'?null:box(svg),radio:box(e.querySelector('input')),title:box(title),description:box(small),style:{bg:s.backgroundColor,border:s.borderColor,radius:s.borderRadius,padding:s.padding,gap:s.gap,shadow:s.boxShadow,outline:s.outline,iconColor:getComputedStyle(svg).color,titleSize:getComputedStyle(title).fontSize,titleWeight:getComputedStyle(title).fontWeight,titleHeight:getComputedStyle(title).lineHeight,descriptionSize:getComputedStyle(small).fontSize,descriptionHeight:getComputedStyle(small).lineHeight,titleColor:getComputedStyle(title).color,descriptionColor:getComputedStyle(small).color}}})}
document.getElementById('dbmsoption-record').onclick=async()=>{const r=await fetch('/evidence/source-dbmsoption.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,width:innerWidth,rows:measurements()})});if(!r.ok)throw Error('Example evidence failed');document.getElementById('dbmsoption-record').textContent='DbmsOption recorded';};
</script>''')
(out/'dbmsoption.html').write_text('\n'.join(parts))
for dest in [out/'dbmsoption-cases.json',r/'docs/replica/source/dbmsoption-cases.json']:dest.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'DbmsOption cases')
